insert into lessons (id, unit_id, position, title_tr, title_en, summary_tr, content, published) values
(1, 1, 1, 'Alfabe ve sesler', 'The Alphabet and Sounds', 'İngiliz alfabesindeki 26 harfi, sesli harfleri ve adını harf harf söylemeyi öğren.', '{"learn":[{"type":"text","tr":"İngiliz alfabesinde **26 harf** var. Harflerin çoğu Türkçedekiyle aynı görünür ama **okunuşları farklıdır**. Aşağıdaki okunuşlar Türkçe harflerle yazıldı. Her harfi dinle ve yüksek sesle tekrar et."},{"type":"table","title_tr":"İngiliz alfabesi (A–Z)","head":["Harf","Okunuş","Harf","Okunuş"],"rows":[["A","ey","N","en"],["B","bi","O","ou"],["C","si","P","pi"],["D","di","Q","kyu"],["E","i","R","ar"],["F","ef","S","es"],["G","ci","T","ti"],["H","eyç","U","yu"],["I","ay","V","vi"],["J","cey","W","dabılyu"],["K","key","X","eks"],["L","el","Y","vay"],["M","em","Z","zed"]]},{"type":"tip","tr":"En çok karışan harfler: **E** “i” okunur, **I** ise “ay”. **G** “ci” okunur, **J** ise “cey”. **A** da “a” değil, “ey” okunur. Bu beşine özellikle dikkat et!"},{"type":"text","tr":"**Sesli harfler (vowels):** A, E, I, O, U. Okunuşları sırayla: ey, i, ay, ou, yu. Geri kalan harflere **sessiz harf (consonant)** denir: B, C, D, F…"},{"type":"table","title_tr":"Türkçeden farklı olanlar","head":["Durum","Harfler"],"rows":[["Türkçede yok, İngilizcede var","Q (kyu), W (dabılyu), X (eks)"],["İngilizcede yok","Ç, Ş, Ğ, I (noktasız ı), Ö, Ü"],["“ç” sesi şöyle yazılır","ch"],["“ş” sesi şöyle yazılır","sh"]]},{"type":"examples","title_tr":"Adını harf harf söylemek","items":[{"en":"How do you spell it?","tr":"Nasıl yazılıyor?","note_tr":"Bir kelimeyi harf harf söylemeyi istemek için."},{"en":"How do you spell your name?","tr":"Adını nasıl yazıyorsun?"},{"en":"My name is Ali. A, L, I.","tr":"Benim adım Ali. A, L, I."},{"en":"Emma. E, double M, A.","tr":"Emma. E, iki tane M, A.","note_tr":"Yan yana iki aynı harf için **double** (dabıl) denir."}]},{"type":"tip","tr":"Adında Türkçe harf varsa, pasaporttaki gibi İngilizce harfle söyle: ç → c, ş → s, ğ → g, ı → i, ö → o, ü → u. Örneğin **Gül** → G, U, L."},{"type":"examples","title_tr":"İki önemli ses: th ve w","items":[{"en":"Thank you.","tr":"Teşekkür ederim.","note_tr":"**th**: Dilinin ucunu üst dişlerinin arasına koy ve hafifçe üfle. “t” ya da “s” deme."},{"en":"three","tr":"üç","note_tr":"Yine **th** sesi: dil dişlerin arasında."},{"en":"W","tr":"dabılyu","note_tr":"**w**: Dudaklarını “u” der gibi yuvarla, sonra aç. Türkçedeki “v” gibi dişini dudağına değdirme."}]}],"listen":[{"en":"A, B, C, D, E, F, G","tr":"A''dan G''ye harfler"},{"en":"H, I, J, K, L, M, N","tr":"H''den N''ye harfler"},{"en":"O, P, Q, R, S, T, U","tr":"O''dan U''ya harfler"},{"en":"V, W, X, Y, Z","tr":"V''den Z''ye harfler"},{"en":"A, E, I, O, U","tr":"Sesli harfler (vowels)"},{"en":"E, I. G, J.","tr":"En çok karışan harfler: i, ay. ci, cey."},{"en":"How do you spell it?","tr":"Nasıl yazılıyor?"},{"en":"How do you spell your name?","tr":"Adını nasıl yazıyorsun?"},{"en":"My name is Ali. A, L, I.","tr":"Benim adım Ali. A, L, I."},{"en":"Emma. E, double M, A.","tr":"Emma. E, iki tane M, A."},{"en":"Thank you.","tr":"Teşekkür ederim. (th sesine dikkat)"}]}'::jsonb, true),
(2, 1, 2, 'Selamlaşma', 'Greetings', 'Selam vermeyi, hâl hatır sormayı, vedalaşmayı ve kibar sözcükleri öğren.', '{"learn":[{"type":"text","tr":"Birini selamlamanın en kolay yolu: **Hello!** (helou) ya da **Hi!** (hay). **Hello** her yerde kullanılır. **Hi** daha samimidir; arkadaşlarla ve ailede kullanılır."},{"type":"table","title_tr":"Günün saatine göre selam","head":["İngilizce","Türkçe","Ne zaman?"],"rows":[["Good morning","Günaydın","Sabah, öğlene kadar"],["Good afternoon","İyi günler","Öğleden sonra"],["Good evening","İyi akşamlar","Akşam, selam verirken"],["Good night","İyi geceler","Gece ayrılırken, yatarken"]]},{"type":"tip","tr":"**Good night** bir selam değildir! Sadece ayrılırken ya da yatmadan önce söylenir. Akşam biriyle karşılaşınca **Good evening** de."},{"type":"examples","title_tr":"Nasılsın?","items":[{"en":"How are you?","tr":"Nasılsın? / Nasılsınız?"},{"en":"I''m fine, thank you. And you?","tr":"İyiyim, teşekkür ederim. Ya sen?","note_tr":"**I''m** = I am (ben …im). Karşındakine de sormak kibarlıktır: **And you?**"},{"en":"I''m OK, thanks.","tr":"İyiyim, sağ ol."},{"en":"Very well, thank you.","tr":"Çok iyiyim, teşekkür ederim.","note_tr":"Biraz daha resmî bir cevap."}]},{"type":"table","title_tr":"Vedalaşma","head":["İngilizce","Türkçe"],"rows":[["Goodbye","Hoşça kal / Güle güle"],["Bye!","Bay bay! / Hoşça kal!"],["See you!","Görüşürüz!"],["See you later!","Sonra görüşürüz!"],["Good night!","İyi geceler!"]]},{"type":"examples","title_tr":"Kibar sözcükler","items":[{"en":"Please.","tr":"Lütfen."},{"en":"Thank you. Thanks.","tr":"Teşekkür ederim. Sağ ol."},{"en":"Thank you very much.","tr":"Çok teşekkür ederim."},{"en":"Sorry!","tr":"Özür dilerim! / Pardon!","note_tr":"Bir hata yaptığında ya da birine çarptığında."},{"en":"Excuse me.","tr":"Affedersiniz.","note_tr":"Birinin dikkatini çekmek ya da yol istemek için."}]},{"type":"table","title_tr":"Resmî mi, samimi mi?","head":["Resmî (iş, yabancılar)","Samimi (arkadaşlar)"],"rows":[["Hello","Hi"],["Goodbye","Bye / See you"],["Thank you","Thanks"],["Very well, thank you.","Fine, thanks."]]},{"type":"tip","tr":"Resmî ortamda soyadıyla birlikte **Mr** (Bay) ya da **Ms** (Bayan) kullanılır: **Good morning, Mr Brown.** Arkadaşına ise sadece adıyla seslen: **Hi, Tom!**"}],"listen":[{"en":"Hello!","tr":"Merhaba!"},{"en":"Hi, Tom!","tr":"Selam, Tom!"},{"en":"Good morning.","tr":"Günaydın."},{"en":"Good afternoon.","tr":"İyi günler."},{"en":"Good evening.","tr":"İyi akşamlar."},{"en":"Good night.","tr":"İyi geceler."},{"en":"How are you?","tr":"Nasılsın?"},{"en":"I''m fine, thank you. And you?","tr":"İyiyim, teşekkür ederim. Ya sen?"},{"en":"Goodbye! See you later.","tr":"Hoşça kal! Sonra görüşürüz."},{"en":"Thank you very much.","tr":"Çok teşekkür ederim."},{"en":"Excuse me.","tr":"Affedersiniz."},{"en":"Sorry!","tr":"Özür dilerim!"}]}'::jsonb, true),
(3, 1, 3, 'Sayılar ve yaş', 'Numbers and Age', '0''dan 100''e kadar saymayı, yaşını söylemeyi ve telefon numarası okumayı öğren.', '{"learn":[{"type":"text","tr":"Sayılar her yerde karşına çıkar: yaş, telefon, fiyat. Önce **0–10** arasını öğren; diğer sayılar bunların üstüne kurulur."},{"type":"table","title_tr":"0–10","head":["Sayı","İngilizce","Okunuş"],"rows":[["0","zero","ziırou"],["1","one","van"],["2","two","tu"],["3","three","thrii (th sesi)"],["4","four","foo"],["5","five","fayv"],["6","six","siks"],["7","seven","sevın"],["8","eight","eyt"],["9","nine","nayn"],["10","ten","ten"]]},{"type":"table","title_tr":"11–20","head":["Sayı","İngilizce","Okunuş"],"rows":[["11","eleven","ilevın"],["12","twelve","tuelv"],["13","thirteen","thöötiin"],["14","fourteen","footiin"],["15","fifteen","fiftiin"],["16","sixteen","sikstiin"],["17","seventeen","sevıntiin"],["18","eighteen","eytiin"],["19","nineteen","nayntiin"],["20","twenty","tuenti"]]},{"type":"table","title_tr":"Onluklar","head":["Sayı","İngilizce"],"rows":[["30","thirty"],["40","forty"],["50","fifty"],["60","sixty"],["70","seventy"],["80","eighty"],["90","ninety"],["100","one hundred"]]},{"type":"tip","tr":"**-teen** ve **-ty** karışmasın! **thirTEEN** (13): vurgu sonda, “tiin” uzun. **THIRty** (30): vurgu başta, “ti” kısa. Aynı kural 13–19 ve 30–90 için de geçerli: fifteen (15) / fifty (50)."},{"type":"tip","tr":"Yazım tuzakları: **forty** (40) içinde “u” yok, four ama forty. **fifty** (50) doğru, “fivety” yanlış. **twelve** (12) ile **twenty** (20) karışmasın."},{"type":"examples","title_tr":"Bileşik sayılar","items":[{"en":"twenty-one","tr":"21","note_tr":"Önce onluk, sonra birlik. Araya kısa çizgi (-) konur."},{"en":"thirty-five","tr":"35"},{"en":"forty-eight","tr":"48"},{"en":"ninety-nine","tr":"99"}]},{"type":"examples","title_tr":"Yaş sormak ve söylemek","items":[{"en":"How old are you?","tr":"Kaç yaşındasın?","note_tr":"**old** = yaşlı, eski. Bu soruda “kaç yaşında” anlamına gelir."},{"en":"I''m 25.","tr":"25 yaşındayım."},{"en":"I''m 25 years old.","tr":"25 yaşındayım.","note_tr":"İkisi de doğru. Ama “I''m 25 years.” yanlış: ya sadece sayı ya da **years old** birlikte."},{"en":"I''m thirteen. And you?","tr":"On üç yaşındayım. Ya sen?"}]},{"type":"examples","title_tr":"Telefon numarası","items":[{"en":"What''s your phone number?","tr":"Telefon numaran ne?","note_tr":"**What''s** = What is (… ne?)"},{"en":"It''s 0 5 3 2, 7 1 4, 2 8 5 6.","tr":"0532 714 2856.","note_tr":"Rakamlar tek tek okunur. 0 için **oh** (ou) ya da **zero** denir."},{"en":"Double five.","tr":"55 (iki tane beş)","note_tr":"Yan yana iki aynı rakam için **double** denir, tıpkı alfabedeki gibi."}]}],"listen":[{"en":"one, two, three, four, five","tr":"bir, iki, üç, dört, beş"},{"en":"six, seven, eight, nine, ten","tr":"altı, yedi, sekiz, dokuz, on"},{"en":"eleven, twelve, thirteen, fourteen, fifteen","tr":"11, 12, 13, 14, 15"},{"en":"sixteen, seventeen, eighteen, nineteen, twenty","tr":"16, 17, 18, 19, 20"},{"en":"thirteen, thirty","tr":"13, 30"},{"en":"fifteen, fifty","tr":"15, 50"},{"en":"forty, sixty, eighty, one hundred","tr":"40, 60, 80, 100"},{"en":"How old are you?","tr":"Kaç yaşındasın?"},{"en":"I''m twenty-five years old.","tr":"Yirmi beş yaşındayım."},{"en":"What''s your phone number?","tr":"Telefon numaran ne?"},{"en":"It''s 0 5 3 2, 7 1 4, 2 8 5 6.","tr":"0532 714 2856."}]}'::jsonb, true),
(4, 1, 4, 'İsim ve ülke söyleme', 'Names and Countries', 'Adını ve nereli olduğunu söylemeyi, ülke ve milliyet adlarını öğren.', '{"learn":[{"type":"text","tr":"Tanışırken iki soru çok önemli: **What''s your name?** (Adın ne?) ve **Where are you from?** (Nerelisin?). Bu derste ikisini de soracak ve cevaplayacaksın."},{"type":"examples","title_tr":"Adını söylemek","items":[{"en":"What''s your name?","tr":"Adın ne?","note_tr":"**What''s** = What is"},{"en":"My name is Elif.","tr":"Benim adım Elif."},{"en":"I''m Elif.","tr":"Ben Elif''im.","note_tr":"Daha kısa ve günlük."},{"en":"Nice to meet you.","tr":"Tanıştığımıza memnun oldum."},{"en":"Nice to meet you, too.","tr":"Ben de memnun oldum.","note_tr":"**too** = de / da"}]},{"type":"examples","title_tr":"Nerelisin?","items":[{"en":"Where are you from?","tr":"Nerelisin?","note_tr":"**where** = nerede, nereye. **from** = -den / -dan."},{"en":"I''m from Turkey.","tr":"Türkiye''denim."},{"en":"I''m from Istanbul.","tr":"İstanbul''danım.","note_tr":"Şehrini de söyleyebilirsin."},{"en":"I''m Turkish.","tr":"Türk''üm."}]},{"type":"table","title_tr":"Ülkeler ve milliyetler","head":["Ülke","Milliyet","Türkçe"],"rows":[["Turkey","Turkish","Türkiye, Türk"],["England","English","İngiltere, İngiliz"],["the UK","British","Birleşik Krallık, Britanyalı"],["the USA","American","ABD, Amerikalı"],["Germany","German","Almanya, Alman"],["France","French","Fransa, Fransız"],["Spain","Spanish","İspanya, İspanyol"],["Italy","Italian","İtalya, İtalyan"],["Japan","Japanese","Japonya, Japon"],["China","Chinese","Çin, Çinli"]]},{"type":"tip","tr":"Ülke ve milliyetler İngilizcede hep **büyük harfle** başlar: Turkey, Turkish. Milliyetle **from** kullanılmaz: **I''m Turkish.** doğru, “I''m from Turkish.” yanlış."},{"type":"text","tr":"Milliyetlerin sonu çoğu zaman şöyle: **-ish** (Turkish, English, Spanish), **-an** (American, German, Italian), **-ese** (Japanese, Chinese). **French** ve **British** ezberlenir."},{"type":"tip","tr":"**the USA** ve **the UK** önüne **the** gelir. Türkiye''nin resmî İngilizce adı artık **Türkiye**; günlük dilde **Turkey** de çok yaygındır. İkisini de duyabilirsin."},{"type":"examples","title_tr":"Kısa bir diyalog","items":[{"en":"Hello! What''s your name?","tr":"Merhaba! Adın ne?","note_tr":"Elif"},{"en":"Hi! I''m Tom. And you?","tr":"Selam! Ben Tom. Ya sen?","note_tr":"Tom"},{"en":"My name is Elif. Nice to meet you.","tr":"Benim adım Elif. Tanıştığımıza memnun oldum.","note_tr":"Elif"},{"en":"Nice to meet you, too. Where are you from?","tr":"Ben de memnun oldum. Nerelisin?","note_tr":"Tom"},{"en":"I''m from Turkey. And you?","tr":"Türkiye''denim. Ya sen?","note_tr":"Elif"},{"en":"I''m from England. I''m English.","tr":"İngiltere''denim. İngilizim.","note_tr":"Tom"}]}],"listen":[{"en":"What''s your name?","tr":"Adın ne?"},{"en":"My name is Elif.","tr":"Benim adım Elif."},{"en":"I''m Tom.","tr":"Ben Tom."},{"en":"Nice to meet you.","tr":"Tanıştığımıza memnun oldum."},{"en":"Nice to meet you, too.","tr":"Ben de memnun oldum."},{"en":"Where are you from?","tr":"Nerelisin?"},{"en":"I''m from Turkey. I''m Turkish.","tr":"Türkiye''denim. Türk''üm."},{"en":"I''m from England. I''m English.","tr":"İngiltere''denim. İngilizim."},{"en":"I''m from the USA. I''m American.","tr":"ABD''denim. Amerikalıyım."},{"en":"I''m from Japan. I''m Japanese.","tr":"Japonya''danım. Japonum."},{"en":"I''m from Spain. I''m Spanish.","tr":"İspanya''danım. İspanyolum."}]}'::jsonb, true),
(5, 1, 5, 'İlk cümleler', 'First Sentences', 'I am, This is ve It is kalıplarıyla renkler ve eşyalar hakkında ilk cümlelerini kur.', '{"learn":[{"type":"text","tr":"Artık harfleri, selamları, sayıları ve ülkeleri biliyorsun. Şimdi bunları birleştirip **cümle** kuralım. Üç kalıp yeter: **I am …**, **This is …**, **It is …**."},{"type":"table","title_tr":"Üç temel kalıp","head":["Kalıp","Örnek","Türkçe"],"rows":[["I am (I''m)","I am Elif. I''m 20.","Ben Elif''im. 20 yaşındayım."],["This is","This is Tom.","Bu Tom."],["It is (It''s)","It''s a book.","O bir kitap."],["That is (That''s)","That''s my car.","Şu benim arabam."]]},{"type":"tip","tr":"Türkçede “Bu bir kitap.” derken fiil yok. İngilizcede ise **is** şart: **This is a book.** doğru, “This a book.” yanlış."},{"type":"text","tr":"**this** = bu: yakındaki, elinde tuttuğun şey. **that** = şu: uzaktaki, parmakla gösterdiğin şey. **a** = bir."},{"type":"examples","title_tr":"this / that ile eşyalar","items":[{"en":"This is a book.","tr":"Bu bir kitap."},{"en":"This is my phone.","tr":"Bu benim telefonum."},{"en":"That is a car.","tr":"Şu bir araba."},{"en":"That''s your bag.","tr":"Şu senin çantan.","note_tr":"**That''s** = That is"},{"en":"What is this? It''s a pen.","tr":"Bu ne? Bir kalem."},{"en":"It''s a cup.","tr":"Bu bir fincan.","note_tr":"**It** şeyler için kullanılır: o (şey)."}]},{"type":"tip","tr":"**this** ve **that** kelimelerinde de **th** var. Dil yine dişlerin arasında, ama bu sefer ses titreşimli: “dis”, “dät” gibi."},{"type":"table","title_tr":"Renkler (colours)","head":["İngilizce","Türkçe","Okunuş"],"rows":[["red","kırmızı","red"],["blue","mavi","bluu"],["green","yeşil","griin"],["yellow","sarı","yelou"],["black","siyah","blek"],["white","beyaz","uayt"],["orange","turuncu","orinc"],["brown","kahverengi","braun"]]},{"type":"tip","tr":"Renk, Türkçedeki gibi isimden **önce** gelir: **a red car** = kırmızı bir araba. Renk sormak için: **What colour is it?** (Ne renk?)"},{"type":"examples","title_tr":"Kısa bir diyalog","items":[{"en":"Hello! I''m Elif. This is Tom.","tr":"Merhaba! Ben Elif. Bu Tom."},{"en":"Hi, Tom! Nice to meet you.","tr":"Merhaba Tom! Tanıştığımıza memnun oldum."},{"en":"Nice to meet you, too.","tr":"Ben de memnun oldum."},{"en":"What is this, Tom?","tr":"Bu ne, Tom?"},{"en":"It''s my phone. It''s black.","tr":"Benim telefonum. Siyah."}]}],"listen":[{"en":"I am Elif.","tr":"Ben Elif''im."},{"en":"I''m from Turkey. I''m 25.","tr":"Türkiye''denim. 25 yaşındayım."},{"en":"This is Tom.","tr":"Bu Tom."},{"en":"This is my book.","tr":"Bu benim kitabım."},{"en":"That is a car.","tr":"Şu bir araba."},{"en":"What is this?","tr":"Bu ne?"},{"en":"It''s a pen.","tr":"Bir kalem."},{"en":"What colour is it?","tr":"Ne renk?"},{"en":"It''s red.","tr":"Kırmızı."},{"en":"It''s a blue bag.","tr":"Mavi bir çanta."},{"en":"That''s a white car.","tr":"Şu beyaz bir araba."},{"en":"This is my phone. It''s black.","tr":"Bu benim telefonum. Siyah."}]}'::jsonb, true),
(6, 2, 1, 'I am / You are', 'The verb ''to be'': I and you', 'Kendini ve karşındakini tanıtmak için am / are kullanmayı öğren: meslekler ve duygular.', '{"learn":[{"type":"text","tr":"İngilizcede “olmak” fiiline **to be** denir. Türkçede bu anlamı ekle veririz: öğrenci**yim**, öğrenci**sin**. İngilizcede ise ayrı bir kelime kullanırız: **I am** (ben …-im) ve **you are** (sen …-sin / siz …-siniz)."},{"type":"table","title_tr":"Uzun ve kısa biçim","head":["Uzun biçim","Kısa biçim","Türkçe"],"rows":[["I am","I''m","Ben …-im"],["You are","You''re","Sen …-sin / Siz …-siniz"]]},{"type":"tip","tr":"Konuşmada hep **kısa biçim** kullanılır: **I''m**, **you''re**. Kesme işareti ( '' ) bir harfin düştüğünü gösterir: I a̶m → I''m."},{"type":"text","tr":"Meslek söylerken isimden önce **a** ya da **an** gelir. Türkçede “Ben öğretmenim” deriz, ama İngilizcede “bir” kelimesi şarttır: **I''m a teacher.** Kelime sesli harf sesiyle (a, e, i, o, u) başlıyorsa **an** kullanılır: **an engineer**, **an actor**."},{"type":"examples","title_tr":"Meslekler","items":[{"en":"I''m a student.","tr":"Ben bir öğrenciyim."},{"en":"You''re a teacher.","tr":"Sen bir öğretmensin."},{"en":"I''m a doctor.","tr":"Ben bir doktorum."},{"en":"You''re an engineer.","tr":"Sen bir mühendissin.","note_tr":"engineer sesli harfle başlar → an"},{"en":"I''m a nurse.","tr":"Ben bir hemşireyim."}]},{"type":"text","tr":"Duygularımızı da **am / are** ile söyleriz. Burada **a / an kullanılmaz**, çünkü bunlar sıfattır: **I''m happy.** (Mutluyum.)"},{"type":"examples","title_tr":"Duygular","items":[{"en":"I''m happy.","tr":"Mutluyum."},{"en":"I''m tired.","tr":"Yorgunum."},{"en":"You''re hungry.","tr":"Açsın."},{"en":"You''re sad.","tr":"Üzgünsün."},{"en":"I''m fine, thank you.","tr":"İyiyim, teşekkür ederim."}]},{"type":"tip","tr":"**You** hem “sen” hem “siz” demektir. Öğretmenine de arkadaşına da **you are** dersin. Kolay, değil mi?"}],"listen":[{"en":"I am a student.","tr":"Ben bir öğrenciyim."},{"en":"I''m a teacher.","tr":"Ben bir öğretmenim."},{"en":"You are a doctor.","tr":"Sen bir doktorsun."},{"en":"You''re an engineer.","tr":"Sen bir mühendissin."},{"en":"I''m a nurse.","tr":"Ben bir hemşireyim."},{"en":"You''re a good student.","tr":"Sen iyi bir öğrencisin."},{"en":"I''m happy today.","tr":"Bugün mutluyum."},{"en":"I''m tired.","tr":"Yorgunum."},{"en":"You''re hungry.","tr":"Açsın."},{"en":"I''m a cook and you''re a waiter.","tr":"Ben bir aşçıyım, sen de bir garsonsun."}]}'::jsonb, true),
(7, 2, 2, 'Kişi zamirleri', 'Subject pronouns with ''to be''', 'I, you, he, she, it, we, they zamirlerini am / is / are ile kullanmayı öğren.', '{"learn":[{"type":"text","tr":"Kişi zamirleri, bir ismin yerine kullandığımız kısa kelimelerdir: ben, sen, o, biz, siz, onlar. İngilizcede cümle **mutlaka** bir zamir ya da isimle başlar. Türkçedeki gibi “Öğrenciyim.” deyip zamiri atamazsın: **I''m a student.**"},{"type":"table","title_tr":"Zamirler ve to be","head":["Zamir","be","Kısa","Türkçe"],"rows":[["I","am","I''m","ben"],["you","are","you''re","sen / siz"],["he","is","he''s","o (erkek)"],["she","is","she''s","o (kadın)"],["it","is","it''s","o (eşya, hayvan)"],["we","are","we''re","biz"],["they","are","they''re","onlar"]]},{"type":"tip","tr":"Kolay kural: **I → am**, **he / she / it → is**, **you / we / they → are**."},{"type":"text","tr":"Türkçede “o” kelimesi herkes için aynıdır. İngilizcede ise üç ayrı “o” vardır: **he** bir erkek için, **she** bir kadın için, **it** bir eşya ya da hayvan için. Ali için **he**, Ayşe için **she**, bir kitap ya da kedi için **it** dersin."},{"type":"examples","title_tr":"He, she, it","items":[{"en":"This is Ali. He''s a doctor.","tr":"Bu Ali. O bir doktor.","note_tr":"Ali erkek → he"},{"en":"This is Ayşe. She''s a teacher.","tr":"Bu Ayşe. O bir öğretmen.","note_tr":"Ayşe kadın → she"},{"en":"This is my cat. It''s black.","tr":"Bu benim kedim. O siyah.","note_tr":"hayvan → it"},{"en":"It''s a book.","tr":"Bu bir kitap.","note_tr":"eşya → it"}]},{"type":"examples","title_tr":"We, you, they","items":[{"en":"We''re students.","tr":"Biz öğrenciyiz.","note_tr":"Çoğulda a / an kullanılmaz, kelimeye -s eklenir."},{"en":"You''re friends.","tr":"Siz arkadaşsınız."},{"en":"They''re from Turkey.","tr":"Onlar Türkiye''den."},{"en":"Ali and Ayşe are doctors.","tr":"Ali ve Ayşe doktor.","note_tr":"Ali and Ayşe = they → are"}]},{"type":"tip","tr":"**It''s** (it is = o …-dır) ile **its** (onun) farklıdır. Kesme işareti varsa “it is” demektir."}],"listen":[{"en":"He is a doctor.","tr":"O bir doktor."},{"en":"She''s a teacher.","tr":"O bir öğretmen."},{"en":"It''s a cat.","tr":"O bir kedi."},{"en":"We''re students.","tr":"Biz öğrenciyiz."},{"en":"They''re from England.","tr":"Onlar İngiltere''den."},{"en":"You''re my friend.","tr":"Sen benim arkadaşımsın."},{"en":"He''s tired.","tr":"O yorgun."},{"en":"She''s happy.","tr":"O mutlu."},{"en":"We are in London.","tr":"Biz Londra''dayız."},{"en":"They are engineers.","tr":"Onlar mühendis."},{"en":"It''s a big dog.","tr":"O büyük bir köpek."}]}'::jsonb, true),
(8, 2, 3, 'Olumsuz cümleler', 'Negative sentences with ''to be''', 'am / is / are sonrasına not ekleyerek “değilim, değil” demeyi öğren.', '{"learn":[{"type":"text","tr":"Türkçede olumsuz için “değil” deriz: Öğretmen **değilim**. İngilizcede **am / is / are** kelimesinden hemen sonra **not** gelir: **I am not a teacher.**"},{"type":"table","title_tr":"Olumsuz biçim","head":["Uzun biçim","Kısa biçim","Türkçe"],"rows":[["I am not","I''m not","ben … değilim"],["you are not","you aren''t / you''re not","sen … değilsin"],["he is not","he isn''t / he''s not","o … değil"],["she is not","she isn''t / she''s not","o … değil"],["it is not","it isn''t / it''s not","o … değil"],["we are not","we aren''t / we''re not","biz … değiliz"],["they are not","they aren''t / they''re not","onlar … değil"]]},{"type":"tip","tr":"**is not → isn''t**, **are not → aren''t**. Ama **am not** için kısa biçim sadece **I''m not** olur. “I amn''t” diye bir şey yoktur!"},{"type":"examples","title_tr":"Örnekler","items":[{"en":"I''m not tired.","tr":"Yorgun değilim."},{"en":"You aren''t a doctor.","tr":"Sen doktor değilsin."},{"en":"He isn''t from Spain.","tr":"O İspanya''dan değil."},{"en":"It isn''t a cat. It''s a dog.","tr":"O bir kedi değil. O bir köpek."},{"en":"We''re not hungry.","tr":"Aç değiliz."}]},{"type":"text","tr":"Olumsuz cümleyi yanlış bir bilgiyi **düzeltmek** için çok kullanırız. Önce “değil” deriz, sonra doğrusunu söyleriz."},{"type":"examples","title_tr":"Yanlışı düzelt","items":[{"en":"London isn''t in Turkey. It''s in England.","tr":"Londra Türkiye''de değil. İngiltere''de."},{"en":"I''m not 20. I''m 25.","tr":"20 yaşında değilim. 25 yaşındayım."},{"en":"She isn''t a nurse. She''s a doctor.","tr":"O hemşire değil. O doktor."},{"en":"They aren''t from Italy. They''re from Spain.","tr":"Onlar İtalya''dan değil. İspanya''dan."},{"en":"The bus isn''t red. It''s blue.","tr":"Otobüs kırmızı değil. Mavi."},{"en":"That isn''t right. It''s wrong.","tr":"O doğru değil. Yanlış."}]},{"type":"tip","tr":"Konuşurken **isn''t** ve **aren''t** çok yaygındır. Yazarken ikisi de doğrudur: “he isn''t” = “he''s not”."}],"listen":[{"en":"I''m not a teacher.","tr":"Ben öğretmen değilim."},{"en":"You aren''t late.","tr":"Geç kalmadın."},{"en":"He isn''t at home.","tr":"O evde değil."},{"en":"She''s not from England.","tr":"O İngiltere''den değil."},{"en":"It isn''t my phone.","tr":"O benim telefonum değil."},{"en":"We aren''t at school.","tr":"Okulda değiliz."},{"en":"They''re not students.","tr":"Onlar öğrenci değil."},{"en":"I''m not 30. I''m 35.","tr":"30 yaşında değilim. 35 yaşındayım."},{"en":"The bag isn''t black. It''s brown.","tr":"Çanta siyah değil. Kahverengi."},{"en":"Ankara isn''t small. It''s very big.","tr":"Ankara küçük değil. Çok büyük."}]}'::jsonb, true),
(9, 2, 4, 'Basit sorular', 'Simple questions with ''to be''', 'Are you…? Is she…? gibi evet/hayır soruları sor, kısa cevap ver ve soru kelimelerini öğren.', '{"learn":[{"type":"text","tr":"Türkçede soru yapmak için **mi** ekleriz: Öğrenci **misin**? İngilizcede ise kelimelerin **yeri değişir**: **am / is / are** cümlenin başına geçer.\n\nYou **are** a student. → **Are** you a student?"},{"type":"table","title_tr":"Evet / hayır soruları","head":["Cümle","Soru","Türkçe"],"rows":[["I am late.","Am I late?","Geç mi kaldım?"],["You are tired.","Are you tired?","Yorgun musun?"],["He is a doctor.","Is he a doctor?","O doktor mu?"],["She is from Spain.","Is she from Spain?","O İspanyol mu?"],["It is your bag.","Is it your bag?","Bu senin çantan mı?"],["They are friends.","Are they friends?","Onlar arkadaş mı?"]]},{"type":"text","tr":"Bu sorulara sadece “Yes” ya da “No” demek biraz kaba durur. **Kısa cevap** verilir: Yes / No + zamir + am / is / are (olumsuzsa not)."},{"type":"examples","title_tr":"Kısa cevaplar","items":[{"en":"Are you a student? Yes, I am.","tr":"Öğrenci misin? Evet, öyleyim."},{"en":"Are you tired? No, I''m not.","tr":"Yorgun musun? Hayır, değilim."},{"en":"Is she a teacher? Yes, she is.","tr":"O öğretmen mi? Evet, öyle."},{"en":"Is he from Italy? No, he isn''t.","tr":"O İtalyan mı? Hayır, değil."},{"en":"Are they hungry? Yes, they are.","tr":"Onlar aç mı? Evet, açlar."}]},{"type":"tip","tr":"Olumlu kısa cevapta kısaltma **yapılmaz**: “Yes, I am.” doğru, “Yes, I''m.” yanlış. Olumsuzda kısaltma serbesttir: “No, I''m not.”"},{"type":"table","title_tr":"Soru kelimeleri","head":["Soru kelimesi","Türkçe","Örnek"],"rows":[["What","Ne","What''s your name?"],["Where","Nerede / Nereden","Where are you from?"],["Who","Kim","Who is she?"],["How old","Kaç yaşında","How old are you?"],["How","Nasıl","How are you?"]]},{"type":"text","tr":"Soru kelimesi her zaman **en başa** gelir, sonra **am / is / are**, sonra kişi. Türkçede soru kelimesi ortada olabilir (Sen **nerelisin**?), ama İngilizcede sıra sabittir: **Where are you from?**"},{"type":"examples","title_tr":"Soru ve cevap","items":[{"en":"Who is he? He''s my teacher.","tr":"O kim? O benim öğretmenim."},{"en":"Where is she from? She''s from Spain.","tr":"O nereli? İspanya''dan."},{"en":"How old is your brother? He''s ten.","tr":"Kardeşin kaç yaşında? On yaşında."},{"en":"What''s this? It''s a phone.","tr":"Bu ne? Bu bir telefon.","note_tr":"What''s = What is"},{"en":"Where is my bag? It''s here.","tr":"Çantam nerede? Burada."}]}],"listen":[{"en":"Are you a student?","tr":"Öğrenci misin?"},{"en":"Yes, I am.","tr":"Evet, öyleyim."},{"en":"Is he a doctor?","tr":"O doktor mu?"},{"en":"No, he isn''t.","tr":"Hayır, değil."},{"en":"Is she from Spain?","tr":"O İspanyol mu?"},{"en":"Are they your friends?","tr":"Onlar senin arkadaşların mı?"},{"en":"Who is she?","tr":"O kim?"},{"en":"Where are you from?","tr":"Nerelisin?"},{"en":"How old is your sister?","tr":"Kız kardeşin kaç yaşında?"},{"en":"What''s this?","tr":"Bu ne?"},{"en":"Where is the teacher?","tr":"Öğretmen nerede?"},{"en":"How are you today?","tr":"Bugün nasılsın?"}]}'::jsonb, true),
(10, 2, 5, 'Tanışma diyalogları', 'Introductions', 'Öğrendiklerini birleştir: sınıfta, otelde ve arkadaşını tanıtırken kısa diyaloglar kur.', '{"learn":[{"type":"text","tr":"Bu ünitede **am / is / are**, zamirler, olumsuz cümleler ve sorular öğrendin. Şimdi hepsini gerçek bir konuşmada kullanma zamanı! Tanışırken en çok duyacağın cümle: **Nice to meet you.** (Tanıştığıma memnun oldum.)"},{"type":"tip","tr":"Biri sana “Nice to meet you.” derse sen de **Nice to meet you, too.** dersin. **too** = “de / da”: “Ben de memnun oldum.”"},{"type":"examples","title_tr":"Diyalog 1: Sınıfta yeni bir arkadaş","items":[{"en":"Hi! I''m Elif. What''s your name?","tr":"Selam! Ben Elif. Senin adın ne?"},{"en":"Hi, Elif. I''m Tom.","tr":"Selam Elif. Ben Tom."},{"en":"Nice to meet you, Tom.","tr":"Tanıştığıma memnun oldum, Tom."},{"en":"Nice to meet you, too. Are you a new student?","tr":"Ben de memnun oldum. Yeni öğrenci misin?"},{"en":"Yes, I am. I''m from Izmir.","tr":"Evet. Ben İzmirliyim."}]},{"type":"examples","title_tr":"Diyalog 2: Otelde","items":[{"en":"Good evening. Welcome to the hotel.","tr":"İyi akşamlar. Otele hoş geldiniz."},{"en":"Good evening. My name is Can Demir.","tr":"İyi akşamlar. Adım Can Demir."},{"en":"Are you Mr Demir from Turkey?","tr":"Türkiye''den Bay Demir siz misiniz?"},{"en":"Yes, I am.","tr":"Evet, benim."},{"en":"Your room is 24. Here''s your key.","tr":"Odanız 24. Buyurun anahtarınız."}]},{"type":"text","tr":"Birini başkasına tanıtırken **This is …** kullanırız. Türkçede “Bu benim arkadaşım Ali.” dediğimiz gibi: **This is my friend, Ali.** Kişiyi gösterirken “he / she” değil, **this** denir."},{"type":"examples","title_tr":"Diyalog 3: Arkadaşını tanıtmak","items":[{"en":"Anna, this is my friend, Ali.","tr":"Anna, bu benim arkadaşım Ali."},{"en":"Hello, Ali. Nice to meet you.","tr":"Merhaba Ali. Tanıştığıma memnun oldum."},{"en":"Nice to meet you, too.","tr":"Ben de memnun oldum."},{"en":"Are you a student, Ali?","tr":"Öğrenci misin, Ali?"},{"en":"No, I''m not. I''m a cook.","tr":"Hayır, değilim. Ben aşçıyım."}]},{"type":"table","title_tr":"Tanışma cümleleri","head":["İngilizce","Türkçe"],"rows":[["Nice to meet you.","Tanıştığıma memnun oldum."],["Nice to meet you, too.","Ben de memnun oldum."],["This is my friend, …","Bu benim arkadaşım …"],["Welcome!","Hoş geldin!"],["See you later.","Sonra görüşürüz."]]},{"type":"tip","tr":"Resmî ortamlarda soyadıyla hitap edilir: erkek için **Mr**, evli kadın için **Mrs**, her kadın için **Ms**. Örnek: **Mr Demir**, **Ms Kaya**. Adın önüne değil, **soyadın** önüne gelir."}],"listen":[{"en":"Nice to meet you.","tr":"Tanıştığıma memnun oldum."},{"en":"Nice to meet you, too.","tr":"Ben de memnun oldum."},{"en":"This is my friend, Ali.","tr":"Bu benim arkadaşım Ali."},{"en":"Are you a new student?","tr":"Yeni öğrenci misin?"},{"en":"Welcome to the hotel.","tr":"Otele hoş geldiniz."},{"en":"My name is Can Demir.","tr":"Adım Can Demir."},{"en":"Here''s your key.","tr":"Buyurun anahtarınız."},{"en":"This is Ms Kaya. She''s our teacher.","tr":"Bu Bayan Kaya. O bizim öğretmenimiz."},{"en":"We''re in the same class.","tr":"Aynı sınıftayız."},{"en":"See you later!","tr":"Sonra görüşürüz!"}]}'::jsonb, true),
