('robinson-crusoe', 'Robinson Crusoe', 'Robinson Crusoe', 'Daniel Defoe', 1719, 'Macera', 'Bir gemi kazasından sonra ıssız bir adada tek başına kalan bir adamın hayatta kalma hikâyesi.', '{"bg":"#1E4E79","fg":"#EEF6FF","accent":"#F4C27A","motif":"island"}'::jsonb, 12, 5, false),
('tom-sawyer', 'The Adventures of Tom Sawyer', 'Tom Sawyer''ın Maceraları', 'Mark Twain', 1876, 'Macera', 'Mississippi kıyısında yaşayan yaramaz Tom''un arkadaşı Huck ile maceraları.', '{"bg":"#8A5A12","fg":"#FFF8E8","accent":"#5FB0E5","motif":"river"}'::jsonb, 12, 6, false),
